import{z as i,x as o,o as E,c as k,q as t,j as A,D as e,d as B,s as l,S as n,b as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Flink 与 Kafka Streams 的对照与收束","description":"","frontmatter":{"title":"Flink 与 Kafka Streams 的对照与收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stream-systems-map.md","filePath":"cs/stream-systems-map.md","lastUpdated":1791413859000}'),m={name:"cs/stream-systems-map.md"};function p(d,a,f,F,c,C){const r=o("Mermaid");return E(),k("div",null,[a[2]||(a[2]=t('<h1 id="flink-与-kafka-streams-的对照与收束" tabindex="-1">Flink 与 Kafka Streams 的对照与收束 <a class="header-anchor" href="#flink-与-kafka-streams-的对照与收束" aria-label="Permalink to &quot;Flink 与 Kafka Streams 的对照与收束&quot;">​</a></h1><div class="epigraph"><p>同一个语义模型可以落在两种架构上：一套独立集群的执行引擎，或一个嵌进应用的库。选哪个不取决于功能表的长短，取决于状态放在谁的运维半径里。</p><footer>—— 据 Apache Flink 与 Kafka Streams 公开设计文档；Kreps, Narkhede and Rao, 2011 整理</footer></div><p><a href="/cs/stream-backpressure">上一课</a>把速率问题收进引擎的有界边。本课收束本课程：先对照两个代表性系统的架构取舍，再把前七课的语义链条收拢成一张图。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>学完模型、窗口、watermark、恰好一次、join、状态、背压，工程上的问题是：这些机制装在哪个壳里。Flink 与 Kafka Streams 是两个极点——前者是独立分布式运行时，后者是嵌在应用进程里的库。逐项对功能表会越对越乱：两边都有窗口、都有恰好一次、都有状态。分得清的是架构与所有权：算力归谁、状态归谁、失效域多大、恢复走哪条路。</p><p><span class="marginnote">直觉类比：独立运行时像请了专职保姆——算力、状态、恢复都有专人管，但要付一份运维钱；嵌入库像自己带娃——状态就放在应用进程里，部署简单，可孩子半夜发烧（实例挂了）得自己爬起来处理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Flink：作业图由 JobManager 编排、TaskManager 执行，状态放 RocksDB，快照写远端存储；事件时间、watermark、<a href="/cs/stream-backpressure">credit 流控</a>都在引擎内，与源的耦合只有一个可重放接口——<a href="/cs/kafka-log">Kafka</a> 只是源之一。Kafka Streams：没有额外集群——分布就是消费组对分区的任务指派；本地 RocksDB 状态加 changelog 主题做备份，恢复等于从 changelog 回放；恰好一次靠把消费-变换-生产包进 Kafka 事务，走的是第四课的路线二而非路线一。并行度上界就是分区数。SQL 层：Flink 的 Table API 在流上跑连续查询；Kafka Streams 的 DSL 与 ksqlDB 是另一条路。</p><p><span class="marginnote">Kafka Streams 的并行度上限是分区数：实例可以少于分区，不能多于。先扩分区再扩应用，会改变键到分区的映射，按键有序随之破坏——扩容决策要提前于业务增长，不是随时可做。</span></p><p><span class="marginnote">数字实例：topic 有 12 个分区，Kafka Streams 应用最多开 12 个有效实例——第 13 个实例永远分不到任务，纯属浪费。Flink 源接 Kafka 时同样受分区数限制，但下游算子想并行 32 就并行 32，与分区数无关。</span></p><p><span class="marginnote">恰好一次的两条路线各对应一家架构：路线一是快照重放——状态定期存盘，故障后连同输入一起回放，全图一致；路线二是日志事务——把消费、变换、生产包进同一个 Kafka 事务，要么全成要么全不成，运维更轻。</span></p>',11)),(E(),A(n,null,{default:e(()=>[l(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E6%AF%8F%E6%9D%A1%E8%AE%B0%E5%BD%95%E8%A6%81%E6%81%B0%E5%A5%BD%E4%B8%80%E6%AC%A1%22%5D%20--%3E%20R1%5B%22%E8%B7%AF%E7%BA%BF%E4%B8%80%EF%BC%9A%E5%BF%AB%E7%85%A7%E9%87%8D%E6%94%BE%22%5D%0A%20%20E%20--%3E%20R2%5B%22%E8%B7%AF%E7%BA%BF%E4%BA%8C%EF%BC%9A%E6%97%A5%E5%BF%97%E4%BA%8B%E5%8A%A1%22%5D%0A%20%20R1%20--%3E%20F%5B%22Flink%EF%BC%9A%E7%8A%B6%E6%80%81%E8%BF%9B%E6%A3%80%E6%9F%A5%E7%82%B9%EF%BC%8C%E6%81%A2%E5%A4%8D%E6%97%B6%E9%87%8D%E6%94%BE%E8%BE%93%E5%85%A5%22%5D%0A%20%20R2%20--%3E%20K%5B%22Kafka%20Streams%EF%BC%9A%E6%B6%88%E8%B4%B9-%E5%8F%98%E6%8D%A2-%E7%94%9F%E4%BA%A7%E5%8C%85%E8%BF%9B%E4%B8%80%E4%B8%AA%E4%BA%8B%E5%8A%A1%22%5D%0A%20%20F%20--%3E%20C1%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E5%85%A8%E5%9B%BE%E4%B8%80%E8%87%B4%EF%BC%8C%E8%BF%90%E7%BB%B4%E5%8D%8A%E5%BE%84%E5%A4%A7%22%5D%0A%20%20K%20--%3E%20C2%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E5%8D%95%E6%BA%90%E5%8D%95%E6%B1%87%E4%B8%80%E8%87%B4%EF%BC%8C%E4%BE%9D%E8%B5%96%20Kafka%20%E8%87%AA%E8%BA%AB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[B("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"真正的分野是状态的运维半径与失效域。Flink 的状态归作业管：扩缩容走 key group 重分配（第六课），快照与作业同生命周期，失效域是整张作业图——一个算子慢，全图背压（第七课）。Kafka Streams 的状态归应用实例管：实例挂，changelog 回放重建本地状态，失效域是单个实例加它负责的分区；跨实例没有整体背压，速率问题由 Kafka 的消费滞后（lag）暴露。故障恢复对应第四课两条路线的取舍：快照重放换整图一致性，日志事务换运维简单。窗口、watermark、迟到合同两边都遵守第二、三课的语义，差别在实现深度：引擎级的水印传播与对齐比库级更精细。语义模型先于引擎——这是本课程最想留下的判断：先写清 WHAT、WHEN、HOW，再挑壳。",-1)),(E(),A(n,null,{default:e(()=>[l(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20FL%5B%22Flink%EF%BC%9A%E7%8B%AC%E7%AB%8B%E8%BF%90%E8%A1%8C%E6%97%B6%22%5D%0A%20%20%20%20JM%5B%22JobManager%EF%BC%9A%E7%BC%96%E6%8E%92%22%5D%20--%3E%20TM%5B%22TaskManager%EF%BC%9A%E6%89%A7%E8%A1%8C%E7%AE%97%E5%AD%90%22%5D%0A%20%20%20%20TM%20--%3E%20ST%5B%22RocksDB%20%E7%8A%B6%E6%80%81%20%2B%20%E8%BF%9C%E7%AB%AF%E5%BF%AB%E7%85%A7%22%5D%0A%20%20end%0A%20%20subgraph%20KST%5B%22Kafka%20Streams%EF%BC%9A%E5%B5%8C%E5%85%A5%E5%BA%94%E7%94%A8%E7%9A%84%E5%BA%93%22%5D%0A%20%20%20%20APP%5B%22%E5%BA%94%E7%94%A8%E7%BA%BF%E7%A8%8B%EF%BC%9A%E6%B6%88%E8%B4%B9%E7%BB%84%E6%8C%87%E6%B4%BE%22%5D%20--%3E%20LOC%5B%22%E6%9C%AC%E5%9C%B0%20RocksDB%20%E7%8A%B6%E6%80%81%22%5D%0A%20%20%20%20LOC%20--%3E%20CL%5B%22changelog%20%E4%B8%BB%E9%A2%98%22%5D%0A%20%20%20%20APP%20--%3E%20LOG%5B%22Kafka%20%E5%88%86%E5%8C%BA%E6%97%A5%E5%BF%97%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">失效域就是「一处出问题时，多大范围被拖下水」：Flink 一个算子慢会背压全图，等于整条流水线降速；Kafka Streams 只影响单个实例与它负责的分区，别的实例照常消费——故障排查与容量评估的粒度因此完全不同。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>对照不构成选型裁决：状态规模、时延要求、团队运维半径、已有 Kafka 投入共同决定；两边也都在演化，快照的边界会过期，语义模型不会。不把「流批一体」当免费午餐：批是特例（第一课），特例的实现路径各有折扣。本课程到此收束：从无界数据的模型出发，经窗口与 watermark 的语义、恰好一次的机制，到 join、状态、背压的工程，最后落回两个系统的架构取舍——后续课程在共识与复制上继续分布式这条线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Flink 是独立运行时：状态归作业，失效域是全图，恢复走快照重放。</li><li>Kafka Streams 是嵌入库：状态归实例，changelog 即 WAL，恢复是回放，并行度上界是分区数。</li><li>恰好一次的两条路线（快照、日志事务）分别对应两家的架构。</li><li>语义模型先于引擎：窗口、进度、幂等的定义不随选型改变。</li><li>出处：Akidau et al., Streaming Systems, O&#39;Reilly 2018；Kreps, Narkhede and Rao, 2011；Flink 与 Kafka Streams 公开设计文档。</li></ul>',5))])}const S=i(m,[["render",p]]);export{D as __pageData,S as default};
